import pandas as pd
from pandas import DatetimeIndex, Timestamp
from pandas.tseries.offsets import QuarterEnd, YearEnd, YearBegin, BYearEnd, HalfYearEnd

dti = DatetimeIndex(["1970-06-15"])
ts = Timestamp("1970-06-15")
offsets = [
    ("QuarterEnd(2**62)", QuarterEnd(2**62)),
    ("YearEnd(2**62)", YearEnd(2**62)),
    ("YearBegin(-(2**63))", YearBegin(-(2**63))),
    ("BYearEnd(2**63-1)", BYearEnd(2**63 - 1)),
    ("HalfYearEnd(-(2**63))", HalfYearEnd(-(2**63))),
]
for name, off in offsets:
    try:
        res = dti + off
        print("ARRAY", name, "->", repr(res[0]))
    except Exception as exc:
        print("ARRAY", name, "-> RAISED", type(exc).__name__, str(exc)[:140])
    try:
        res = ts + off
        print("SCALAR", name, "->", repr(res))
    except Exception as exc:
        print("SCALAR", name, "-> RAISED", type(exc).__name__, str(exc)[:140])
try:
    print("representable YearEnd(2) ->", repr(dti + YearEnd(2)))
except Exception as exc:
    print("representable YearEnd(2) -> RAISED", type(exc).__name__, str(exc)[:140])
